  const totalRow = await first<{ n: number }>(c.env.DB, `SELECT COUNT(*) AS n FROM library_files WHERE ${where.join(' AND ')}`, params);
  const total = totalRow?.n ?? 0;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
