async function searchAll(db: D1Database, q: string): Promise<{ type: string; label: string; title: string; url: string }[]> {
  const like = `%${q}%`;
  const articles = await query<any>(
    db,
    "SELECT id, title FROM articles WHERE status='published' AND type='article' AND title LIKE ? ORDER BY published_at DESC LIMIT 20",
    [like]
  );
  const products = await query<any>(
    db,
    'SELECT id, name AS title FROM products WHERE status = 1 AND name LIKE ? ORDER BY created_at DESC LIMIT 20',
    [like]
  );
  const courses = await query<any>(
    db,
    'SELECT id, title FROM courses WHERE status = 1 AND title LIKE ? ORDER BY created_at DESC LIMIT 20',
    [like]
  );
  const library = await query<any>(
    db,
    "SELECT id, filename FROM library_files WHERE status = 1 AND (filename LIKE ? OR description LIKE ?) ORDER BY id DESC LIMIT 20",
    [like, like]
  );
  const payOptions = await query<any>(
    db,
    'SELECT id, name FROM pay_options WHERE status = 1 AND (name LIKE ? OR account_info LIKE ? OR link_url LIKE ?) ORDER BY sort_order ASC, id ASC LIMIT 20',
    [like, like, like]
  );
  return [
    ...articles.map((a: { id: number; title: string }) => ({ type: 'article', label: 'Articles', title: a.title, url: `/article/${a.id}` })),
    ...products.map((p: { id: number; title: string }) => ({ type: 'product', label: 'Products', title: p.title, url: `/product/${p.id}` })),
    ...courses.map((c: { id: number; title: string }) => ({ type: 'course', label: 'Courses', title: c.title, url: `/course/${c.id}` })),
    ...library.map((l: { id: number; filename: string }) => ({ type: 'library', label: 'Library', title: l.filename, url: `/library` })),
    ...payOptions.map((p: { id: number; name: string }) => ({ type: 'payoption', label: 'Pay Options', title: p.name, url: `/pay-options` })),
  ];
}

