// Resend verification email (logged-in users whose link may have expired)
app.post('/api/account/resend-verification', async (c) => {
  const token = await currentUser(c.env, c.req.raw);
  if (!token) return json({ error: 'Please log in' }, 401);
  const user = await first<{ id: number; email: string; email_verified: number }>(
    c.env.DB,
    'SELECT id, email, email_verified FROM users WHERE id = ?',
    [token.uid]
  );
  if (!user) return json({ error: 'User not found' }, 404);
  if (user.email_verified) return json({ ok: true, already_verified: true });
  const verifyToken = generateVerifyToken();
  await run(c.env.DB, "UPDATE users SET verify_token = ?, updated_at = datetime('now') WHERE id = ?", [verifyToken, user.id]);
  const base = siteBase(c.env);
  const siteName = await getSetting(c.env.DB, 'site_name', '财经资讯站');
  const result = await sendEmail(
    c.env,
    user.email,
    `Verify your email - ${siteName}`,
    `Click the link to verify your email: ${base}/api/verify-email?token=${verifyToken}\n\nIf this wasn't you, ignore this email.`,
    undefined,
    'register_verify'
  );
  if (!result.ok) return json({ error: 'Email service not configured' }, 500);
  return json({ ok: true });
});

app.post('/api/forgot-password', async (c) => {
  const body = await c.req.json().catch(() => ({}));
  const email = String(body.email || '').trim().toLowerCase();
  if (!email) return json({ error: 'Enter email' }, 400);
  const user = await first<{ id: number }>(c.env.DB, 'SELECT id FROM users WHERE email = ?', [email]);
  if (user) {
    const token = generateVerifyToken();
    const expires = new Date(Date.now() + 30 * 60 * 1000).toISOString();
    await run(c.env.DB, "UPDATE users SET reset_token = ?, reset_expires_at = ?, pending_password_hash = '' WHERE id = ?", [token, expires, user.id]);
    const link = `${siteBase(c.env)}/reset-password?token=${token}`;
    const siteName = await getSetting(c.env.DB, 'site_name', '财经资讯站');
    await sendEmail(c.env, email, `Reset password - ${siteName}`, `Click the link to reset (valid 30 min): \n${link}\n\nIf this wasn't you, ignore this email.`, `<p>Please click <a href="${link}">here</a> reset password (valid for 30 minutes).</p>`, 'password_reset');
  }
  return json({ ok: true, message: 'If registered, reset email sent' });
});

app.post('/api/change-password', async (c) => {
  const user = await loadUser(c.env, c.req.raw);
  if (!user) return json({ error: 'Not logged in' }, 401);
  const body = await c.req.json().catch(() => ({}));
  const oldPassword = String(body.old_password || '');
  const newPassword = String(body.new_password || '');
  if (newPassword.length < 6) return json({ error: 'New password at least 6 characters' }, 400);
  if (oldPassword === newPassword) return json({ error: 'New password must differ from current' }, 400);
  const full = await first<{ email: string; password_hash: string }>(c.env.DB, 'SELECT email, password_hash FROM users WHERE id = ?', [user.id]);
  if (!full) return json({ error: 'User not found' }, 404);
  const ok = await verifyPassword(oldPassword, full.password_hash);
  if (!ok) return json({ error: 'Wrong current password' }, 401);
  const token = generateVerifyToken();
  const expires = new Date(Date.now() + 30 * 60 * 1000).toISOString();
  const pendingHash = await hashPassword(newPassword);
  await run(c.env.DB, 'UPDATE users SET reset_token = ?, reset_expires_at = ?, pending_password_hash = ? WHERE id = ?', [token, expires, pendingHash, user.id]);
  const link = `${siteBase(c.env)}/reset-password?token=${token}`;
  const siteName = await getSetting(c.env.DB, 'site_name', '财经资讯站');
  await sendEmail(c.env, full.email, `Confirm password change - ${siteName}`, `Click the link to confirm (valid 30 min): \n${link}\n\nIf this wasn't you, ignore this email.`, `<p>Please click <a href="${link}">here</a> confirm password change (valid for 30 minutes).</p>`, 'password_change');
  return json({ ok: true, message: 'Verification email sent, please confirm via the link' });
});

