  const cat = c.req.query('category') ? parseInt(c.req.query('category') || '', 10) : null;
  const page = Math.max(1, parseInt(c.req.query('page') || '1', 10) || 1);
  const pageSize = Math.min(100, Math.max(1, parseInt(c.req.query('page_size') || '10', 10) || 10));
  const offset = (page - 1) * pageSize;
  const where: string[] = [];
  const params: unknown[] = [];
  if (cat) { where.push('category_id = ?'); params.push(cat); }
  if (q) { where.push('(filename LIKE ? OR ext LIKE ?)'); params.push(`%${q}%`, `%${q}%`); }
